import React from 'react';
import { useParams, useLocation, useNavigate } from 'react-router-dom';
import { motion } from 'framer-motion';
import { ArrowLeft, FileText } from 'lucide-react';
import './Reader.css';

const Reader = () => {
  const { id } = useParams();
  const location = useLocation();
  const navigate = useNavigate();
  
  const pdfData = location.state?.pdf || {
    id: id,
    title: 'Document.pdf',
    pages: 1
  };
  
  const mode = location.state?.mode || 'original';
  const ocrComplete = location.state?.ocrComplete || false;

  const handleBack = () => {
    navigate('/dashboard');
  };

  return (
    <div className="reader">
      <motion.div 
        className="reader-container"
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.5 }}
      >
        {/* Header */}
        <div className="reader-header">
          <button className="back-button" onClick={handleBack}>
            <ArrowLeft size={20} />
            Back to Dashboard
          </button>
          <div className="document-info">
            <FileText size={20} />
            <span className="document-title">{pdfData.title}</span>
            <span className="document-mode">
              {mode === 'reflow' ? 'Reflow Mode' : 'Original Mode'}
              {ocrComplete && ' (OCR Complete)'}
            </span>
          </div>
        </div>

        {/* Content Area */}
        <div className="reader-content">
          <div className="placeholder-content">
            <FileText size={48} />
            <h2>PDF Reader</h2>
            <p>This is a placeholder for the PDF reader component.</p>
            <p>Mode: <strong>{mode}</strong></p>
            {ocrComplete && <p>✅ OCR processing completed successfully</p>}
          </div>
        </div>
      </motion.div>
    </div>
  );
};

export default Reader;
